insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — summary — u-sum-2023 (WEAK)', 'engineering_leadership', 'lead', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-sum-2023","ingestionVersion":"operator_cv_ingestion_v1","kind":"anti_pattern_example","unitId":"u-sum-2023","quality":"WEAK","contentType":"summary","dimensionIds":["professional_summary","evidence_specificity","language_quality"],"evaluation":"Claims breadth ('broad set of skills', 'different sectors', 'various domains') instead of one identity; 'revolutionized' and 'crafting innovative solutions' are buzzword filler; 'enhancing quality by 95%' is an unverifiable metric; ends with a 'seeking to leverage' objective. Classic generic summary the methodology's summary rubric warns against.","reviewFlagIds":["flag-quality-95","flag-years-drift"],"reusable":{"contentClass":["LANGUAGE_PATTERN"],"patternText":"[Title] with over [N] years of a broad set of skills applicable across different sectors, crafting innovative solutions… seeking to leverage my expertise…","lesson":"A summary that claims breadth in every direction positions the candidate in none. Buzzword verbs plus an unverifiable percentage plus a 'seeking' objective is the canonical weak-summary shape — a strong BEFORE example."},"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2023-lead"],"rawText":"Engineering Leader with over 6 years of a broad set of skills applicable across different sectors and roles, crafting innovative solutions for top companies. I have successfully revolutionized digital channels of apps and web platforms, enhancing quality by 95% and driving substantial profitability across various development domains. … Seeking to leverage my expertise as an engineer to enhance business operations through my IT and leadership skills."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — summary — u-sum-2024em (WEAK)', 'engineering_leadership', 'manager', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-sum-2024em","ingestionVersion":"operator_cv_ingestion_v1","kind":"anti_pattern_example","unitId":"u-sum-2024em","quality":"WEAK","contentType":"summary","dimensionIds":["professional_summary","seniority_alignment"],"evaluation":"Same generic body as v1 with only the title and years changed. A manager-level document whose summary is interchangeable with a mid-level one — the title claims more than the register delivers (seniority_alignment warning).","reviewFlagIds":["flag-quality-95","flag-years-drift"],"reusable":{"contentClass":["LANGUAGE_PATTERN"],"patternText":"[Bigger title] + [same generic summary body as the previous version]","lesson":"Raising the title without raising the register is a seniority-alignment failure: a manager summary must add scope, team, and outcome signals, not just a new job title on old prose."},"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2024-em"],"rawText":"Engineering Manager with over 7 years of a broad set of skills applicable across different sectors and roles, crafting innovative solutions for top companies. … Seeking to leverage my expertise as an engineer to enhance business operations through my IT and leadership skills."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — summary — u-sum-mgmt (ACCEPTABLE)', 'engineering_leadership', 'manager', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-sum-mgmt","ingestionVersion":"operator_cv_ingestion_v1","kind":"cv_unit","unitId":"u-sum-mgmt","quality":"ACCEPTABLE","contentType":"summary","dimensionIds":["professional_summary","positioning","evidence_specificity"],"evaluation":"Real structural progress: names level, domains, team composition, and a regulatory specialization — a reader can say who this is. Held back by 'proven track record' boilerplate and the unverifiable 'quality by 95%'. Acceptable, not a primary example.","reviewFlagIds":["flag-quality-95","flag-years-drift"],"reusable":{"contentClass":["STRUCTURAL_PATTERN"],"patternText":"[Role] with [N]+ years leading [team type] across [domain 1], [domain 2] — managing cross-functional squads ([functions]) to deliver [solution type], with expertise in [regulatory/domain specialization].","lesson":"Identity + domains + team composition + specialization is a sound manager-summary skeleton; it degrades only where boilerplate ('proven track record') and unverifiable numbers creep in."},"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2025-mgmt-a","opcv-2025-mgmt-b"],"rawText":"Engineering Leader with 8+ years of experience leading high-performing software engineering teams across Fintech, semi-government, and innovation ecosystems. Proven track record of managing cross-functional squads (Backend, Frontend, QA) to deliver scalable payment and digital solutions while improving platform quality by 95%. Expert in driving technical roadmaps, fostering a culture of mentorship, and ensuring compliance with SAMA frameworks and Saudi regulations."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — summary — u-sum-arch (ACCEPTABLE)', 'engineering_leadership', 'manager', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-sum-arch","ingestionVersion":"operator_cv_ingestion_v1","kind":"cv_unit","unitId":"u-sum-arch","quality":"ACCEPTABLE","contentType":"summary","dimensionIds":["professional_summary","positioning"],"evaluation":"Same skeleton as v3 retargeted at architecture — a deliberate positioning variant per target role, which is itself good practice. Same weaknesses: 'proven track record', 'seamless', unverifiable 95%.","reviewFlagIds":["flag-quality-95","flag-years-drift"],"reusable":{"contentClass":["STRUCTURAL_PATTERN"],"patternText":"[Same summary skeleton], with the specialization slot swapped to match a different target role.","lesson":"Maintaining summary variants that swap only the specialization slot per target role is a legitimate targeting technique — the skeleton stays truthful, only emphasis moves."},"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2025-arch-a","opcv-2025-arch-b"],"rawText":"Engineering Leader with 8+ years of experience leading high-performing software engineering teams across Fintech, semi-government, and innovation ecosystems. Proven track record of managing cross-functional squads to deliver scalable System Architecture and digital solutions while improving platform quality by 95%. Expert in driving technical roadmaps, defining CI/CD processes, and ensuring seamless IT Integration within SAMA frameworks."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — summary — u-sum-2026 (STRONG)', 'engineering_leadership', 'manager', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-sum-2026","ingestionVersion":"operator_cv_ingestion_v1","kind":"cv_unit","unitId":"u-sum-2026","quality":"STRONG","contentType":"summary","dimensionIds":["professional_summary","positioning","seniority_alignment"],"evaluation":"Best of the five: one coherent identity (EM, fintech/digital, banking+government), no fake metrics, no 'seeking' objective, leadership and technical depth both present. Weakness: the middle sentence is a comma-list of technologies that pads length — noted in the lesson, and why this is a structural example rather than a copy-model.","reviewFlagIds":["flag-years-drift"],"reusable":{"contentClass":["STRUCTURAL_PATTERN"],"patternText":"[Role] with [N]+ years leading [team type] in [domain], delivering [platform type] across [sectors]. Experienced in [2–3 technical areas]. Strong background [collaboration surface] while [leadership signal] and [strategic signal].","lesson":"Identity + domain + sectors first, technical depth second, leadership/strategy last — a manager summary in three sentences with zero invented numbers. Trim the technology list to the 2–3 areas the target role cares about."},"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2026-em"],"rawText":"Engineering Manager with 9+ years of experience leading cross-functional engineering teams in fintech and digital products, delivering scalable web and mobile platforms across banking and government sectors. Experienced in system architecture, microservices-based ecosystems, REST API integrations, CI/CD pipelines, cloud-native engineering practices, and engineering excellence. Strong background collaborating with backend, DevOps, and product teams to build secure, high-performance, and scalable digital platforms while mentoring engineers and driving technical strategy."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — bullet — u-arj-impl-2023 (WEAK)', 'software_engineering', 'senior', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-arj-impl-2023","ingestionVersion":"operator_cv_ingestion_v1","kind":"anti_pattern_example","unitId":"u-arj-impl-2023","quality":"WEAK","contentType":"bullet","dimensionIds":["experience_quality","language_quality"],"evaluation":"'With extensive knowledge of' praises the author instead of describing work; parenthesized technology dump; 'seamless user experience' is filler; grammar errors ('JavaScripts', stray spaces). The real facts (built the app, 95% positive feedback) survive despite the writing — bullet-quality ~2.","reviewFlagIds":[],"reusable":{"contentClass":["LANGUAGE_PATTERN"],"patternText":"Implemented and designed [product] with extensive knowledge of ([technology dump]) resulting in a seamless user experience…","lesson":"'With extensive knowledge of' + a parenthesized tech dump is self-praise, not evidence. Technologies belong inside the action ('built X using Y'), and 'seamless' adds nothing a fact wouldn't say better."},"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2023-lead"],"rawText":"Implemented and designed alrajhi mobile app with extensive knowledge of ( JavaScripts, Redux, REST API, Unit Testing, and Figma) resulting in a seamless user experience and 95% positive user feedback."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — achievement — u-arj-led-2026 (STRONG)', 'software_engineering', 'senior', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-arj-led-2026","ingestionVersion":"operator_cv_ingestion_v1","kind":"cv_unit","unitId":"u-arj-led-2026","quality":"STRONG","contentType":"achievement","dimensionIds":["experience_quality","achievement_impact","evidence_specificity"],"evaluation":"Ownership verb, named product, technologies inside the action, two source-supported outcomes, and honest attribution ('contributing to' — not claiming the whole result alone). Bullet-quality 5. The refined descendant of u-arj-impl-2023.","reviewFlagIds":[],"reusable":{"contentClass":["STRUCTURAL_PATTERN"],"patternText":"Led the development of [product] using [core technologies], contributing to [verified outcome 1] and [verified outcome 2].","lesson":"ACTION + PRODUCT + TECHNOLOGY + VERIFIED OUTCOME with honest attribution: 'contributing to' credits a real personal role in a team result without overclaiming."},"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2026-em"],"rawText":"Led the development of the Al Rajhi mobile application using React Native, JavaScript, Redux, and TypeScript, contributing to a 95% positive user satisfaction rate and a 90% increase in application downloads."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — achievement — u-arj-downloads-2023 (ACCEPTABLE)', 'software_engineering', 'senior', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-arj-downloads-2023","ingestionVersion":"operator_cv_ingestion_v1","kind":"cv_unit","unitId":"u-arj-downloads-2023","quality":"ACCEPTABLE","contentType":"achievement","dimensionIds":["achievement_impact","experience_quality"],"evaluation":"Outcome-first structure (result → mechanism → tools) is sound and the metric is source-supported. 'Improved user experience' is an assertion without an observable; ownership is implicit rather than stated.","reviewFlagIds":[],"reusable":{"contentClass":["STRUCTURAL_PATTERN"],"patternText":"Improved [outcome] and increased [measured result] through the development and design of [product] using [tools].","lesson":"OUTCOME + MECHANISM + TOOLS: leading with the result is a legitimate alternative to leading with the action — provided the result is a measured fact."},"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2023-lead","opcv-2024-em","opcv-2025-mgmt-a","opcv-2025-mgmt-b","opcv-2025-arch-a","opcv-2025-arch-b"],"rawText":"Improved user experience and increased app downloads by 90% through the development and design of the Alrajhi mobile app using React Native and Figma."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — technical — u-arj-sarie-2023 (ACCEPTABLE)', 'software_engineering', 'senior', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-arj-sarie-2023","ingestionVersion":"operator_cv_ingestion_v1","kind":"cv_unit","unitId":"u-arj-sarie-2023","quality":"ACCEPTABLE","contentType":"technical","dimensionIds":["experience_quality","evidence_specificity"],"evaluation":"Names a real named system and a purpose — concrete and checkable. But 'managed integrations' hides what the person actually did, and there is no outcome.","reviewFlagIds":[],"reusable":{"contentClass":["STRUCTURAL_PATTERN"],"patternText":"Managed [system type] integrations with [product] to [business purpose] ([named external system]).","lesson":"Naming the specific external system is strong evidence texture; the bullet still needs the person's own mechanism (built? designed? operated?) to score above 3."},"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2023-lead","opcv-2024-em"],"rawText":"Managed core banking system integrations with retail app to streamline financial operations ( Sarie - Saudi Payments )."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — technical — u-arj-middleware (STRONG)', 'software_engineering', 'senior', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-arj-middleware","ingestionVersion":"operator_cv_ingestion_v1","kind":"cv_unit","unitId":"u-arj-middleware","quality":"STRONG","contentType":"technical","dimensionIds":["experience_quality","evidence_specificity"],"evaluation":"The improved descendant of u-arj-sarie-2023: the person's mechanism is now explicit (developed Java middleware) and connected to a named system and purpose. No metric — and none needed; bullet-quality 4 without a number, exactly what the methodology says a metric-free 4 looks like.","reviewFlagIds":[],"reusable":{"contentClass":["STRUCTURAL_PATTERN"],"patternText":"Optimized [system area] by developing [the thing you built] to interface with [named external system] for [business purpose].","lesson":"ACTION + MECHANISM + NAMED SYSTEM + PURPOSE. A technical bullet earns credibility from the concrete thing built and the named system it talks to — no percentage required."},"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2024-em","opcv-2025-mgmt-a","opcv-2025-mgmt-b","opcv-2025-arch-a","opcv-2025-arch-b"],"rawText":"Optimized core banking integrations by developing Java-based middleware to interface with the Sarie (Saudi Payments) system for streamlined financial operations."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — technical — u-arj-frontarch-2026 (STRONG)', 'software_engineering', 'senior', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-arj-frontarch-2026","ingestionVersion":"operator_cv_ingestion_v1","kind":"cv_unit","unitId":"u-arj-frontarch-2026","quality":"STRONG","contentType":"technical","dimensionIds":["experience_quality","leadership_ownership"],"evaluation":"Senior-level craft leadership without people management: established practices others then work within, with an honest qualitative purpose instead of a manufactured metric. Exactly the informal-leadership signal the seniority model expects at senior.","reviewFlagIds":[],"reusable":{"contentClass":["STRUCTURAL_PATTERN"],"patternText":"Established [architecture/practice 1], [practice 2], and [practice 3] to improve [qualitative outcome].","lesson":"Practice-establishment bullets show senior influence without direct reports. Their outcome is legitimately qualitative — do not bolt a number onto maintainability."},"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2026-em"],"rawText":"Established Clean Architecture, reusable component libraries, engineering standards, and code review practices to improve maintainability and application quality."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — bullet — u-arj-collab-2026 (WEAK)', 'software_engineering', 'senior', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-arj-collab-2026","ingestionVersion":"operator_cv_ingestion_v1","kind":"anti_pattern_example","unitId":"u-arj-collab-2026","quality":"WEAK","contentType":"bullet","dimensionIds":["experience_quality"],"evaluation":"'Worked closely with' is a participation verb — the stakeholder list is good context, but nothing here says what the person owned or changed. Bullet-quality 1–2.","reviewFlagIds":[],"reusable":{"contentClass":["LANGUAGE_PATTERN"],"patternText":"Worked closely with [stakeholder list] to deliver [adjective] [product area].","lesson":"A stakeholder list attached to 'worked closely with' is context without ownership. Fold the collaboration into a bullet that states what the person owned within it."},"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2026-em"],"rawText":"Worked closely with Product Managers, UX/UI designers, backend engineers, and QA teams to deliver secure, customer-focused mobile banking experiences."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — leadership — u-arj-rd-2023 (WEAK)', 'engineering_leadership', 'senior', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-arj-rd-2023","ingestionVersion":"operator_cv_ingestion_v1","kind":"anti_pattern_example","unitId":"u-arj-rd-2023","quality":"WEAK","contentType":"leadership","dimensionIds":["leadership_ownership","evidence_specificity"],"evaluation":"A department-leadership claim with no scope (team size? remit?) and a vapor outcome ('improved customer satisfaction' — no observable). 'Led' is doing work the evidence doesn't back up; every noun is generic.","reviewFlagIds":[],"reusable":{"contentClass":["LANGUAGE_PATTERN"],"patternText":"Led the [department] to focus on [theme] and [theme], delivering [generic outcome] through [generic method].","lesson":"Leadership claims need scope and a checkable result; 'led X to focus on Y' with no team size and no observable outcome reads as participation dressed as leadership."},"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2023-lead","opcv-2024-em"],"rawText":"Led the R&D dept. to focus on customer experience & innovation, delivering new features with improved customer satisfaction through real-time data analysis."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — achievement — u-emk-revamp-2023 (ACCEPTABLE)', 'software_engineering', 'lead', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-emk-revamp-2023","ingestionVersion":"operator_cv_ingestion_v1","kind":"cv_unit","unitId":"u-emk-revamp-2023","quality":"ACCEPTABLE","contentType":"achievement","dimensionIds":["achievement_impact","language_quality"],"evaluation":"The underlying fact is strong (owned an app revamp; reviews grew measurably — a countable observable). The writing undercuts it: 'successful' and 'advanced tech' are self-graded adjectives and the tech-dump parens return. This is the ORIGINAL, plausible form of the metric that later versions mutated (see flag).","reviewFlagIds":["flag-satisfaction-150"],"reusable":{"contentClass":["STRUCTURAL_PATTERN"],"patternText":"Led the revamp of [product]; developed and designed [scope], resulting in [countable observable, e.g. growth in reviews/downloads].","lesson":"'Positive reviews grew' is a countable observable — a well-chosen metric. Never let a later edit swap the measured noun for a grander abstract one ('satisfaction')."},"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2023-lead","opcv-2024-em"],"rawText":"Led successful revamp of the Emkan App with advanced tech (Open AI, Figma, React Native, Rive). Developed and designed the app, which resulted in a 150% increase in positive reviews from customers."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — bullet — u-emk-portal-2023 (WEAK)', 'software_engineering', 'lead', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-emk-portal-2023","ingestionVersion":"operator_cv_ingestion_v1","kind":"anti_pattern_example","unitId":"u-emk-portal-2023","quality":"WEAK","contentType":"bullet","dimensionIds":["experience_quality","achievement_impact","language_quality"],"evaluation":"'Cutting-edge' is decoration; the outcome — 'which led to customer satisfaction' — is the emptiest possible result clause: unfalsifiable, unmeasured, ungrounded. Bullet-quality 1–2 despite a real underlying project.","reviewFlagIds":[],"reusable":{"contentClass":["LANGUAGE_PATTERN"],"patternText":"Implemented a cutting-edge revamp of [product], using ([tech dump]) which led to customer satisfaction.","lesson":"'Which led to customer satisfaction' is the canonical vapor outcome — it asserts a feeling, not a change. Either state a real observable or end the bullet at the concrete work."},"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2023-lead","opcv-2024-em"],"rawText":"Implemented a cutting-edge revamp of the Emkan web merchant portal, using (React, JavaScript, TypeScript, and Figma) which led to customer satisfaction."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — achievement — u-emk-portal-2026 (ACCEPTABLE)', 'software_engineering', 'lead', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-emk-portal-2026","ingestionVersion":"operator_cv_ingestion_v1","kind":"cv_unit","unitId":"u-emk-portal-2026","quality":"ACCEPTABLE","contentType":"achievement","dimensionIds":["achievement_impact","evidence_specificity"],"evaluation":"Structurally the strongest portal bullet — platform framing, named systems, collaboration surface. But the closing metric is the mutated form ('customer satisfaction by 150%', not the source's 'positive reviews'): an implausible-sounding claim the methodology says to flag, not admire. Acceptable structure; the metric is quarantined by flag-satisfaction-150.","reviewFlagIds":["flag-satisfaction-150"],"reusable":{"contentClass":["STRUCTURAL_PATTERN"],"patternText":"Modernized [platform] by [improvement area] and collaborating with [teams] on [system types] supporting [named infrastructure], [outcome slot — verified metric only].","lesson":"Platform bullets gain credibility from named infrastructure and collaboration surface; they lose it instantly when the tail metric measures an abstraction (a feeling 'increased by' a triple-digit percentage). Keep the structure, verify the tail."},"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2026-em"],"rawText":"Modernized core merchant platforms by improving user experience and collaborating with backend teams on REST APIs, microservices, and distributed systems supporting PostgreSQL, MySQL, Redis, and Kafka-based integrations, increasing customer satisfaction by 150%."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — technical — u-emk-arch-2026 (ACCEPTABLE)', 'software_engineering', 'lead', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-emk-arch-2026","ingestionVersion":"operator_cv_ingestion_v1","kind":"cv_unit","unitId":"u-emk-arch-2026","quality":"ACCEPTABLE","contentType":"technical","dimensionIds":["experience_quality","leadership_ownership"],"evaluation":"Clean lead-level framing (led architecture + development, principles named) but no scope (how many apps? what scale?) and no outcome. A solid opening bullet that needs a companion carrying the result.","reviewFlagIds":[],"reusable":{"contentClass":["STRUCTURAL_PATTERN"],"patternText":"Led the architecture and development of [application type] using [technologies], following [architectural approach].","lesson":"An architecture-ownership bullet establishes altitude; pair it with an outcome bullet — one bullet rarely carries both well."},"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2026-em"],"rawText":"Led the architecture and development of scalable web and mobile applications using React, React Native, Next.js, and TypeScript, following Clean Architecture principles."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — achievement — u-emk-push-2023 (ACCEPTABLE)', 'software_engineering', 'lead', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-emk-push-2023","ingestionVersion":"operator_cv_ingestion_v1","kind":"cv_unit","unitId":"u-emk-push-2023","quality":"ACCEPTABLE","contentType":"achievement","dimensionIds":["achievement_impact","language_quality"],"evaluation":"Specific feature area, named tools, measured outcome. Phrasing is awkward ('for improved engagement by 80%' — the preposition mangles the claim) and 'engagement' could name its observable. Facts fine, language costs it.","reviewFlagIds":[],"reusable":{"contentClass":["STRUCTURAL_PATTERN"],"patternText":"Redesigned [feature area] with [tools], improving [engagement observable] by [measured amount].","lesson":"A real metric can still read badly: 'for improved X by N%' is grammatically tangled. Strong bullets put the verb on the outcome — 'improving X by N%'."},"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2023-lead","opcv-2024-em"],"rawText":"Redesigned and modernized Emkan app's push notifications with Clevertap, Countly, and Dynatrace for improved engagement by 80%."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — technical — u-emk-cicd-2026 (ACCEPTABLE)', 'software_engineering', 'lead', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-emk-cicd-2026","ingestionVersion":"operator_cv_ingestion_v1","kind":"cv_unit","unitId":"u-emk-cicd-2026","quality":"ACCEPTABLE","contentType":"technical","dimensionIds":["experience_quality"],"evaluation":"Honest cross-team delivery bullet — 'partnered' is truthful about shared work, deliverables are concrete. No outcome, and four deliverables in one line dilutes each.","reviewFlagIds":[],"reusable":{"contentClass":["STRUCTURAL_PATTERN"],"patternText":"Partnered with [teams] to deliver [deliverable 1], [deliverable 2], and [deliverable 3] using [key tool].","lesson":"'Partnered with' is the honest verb for genuinely shared work — better than inflating to 'led'. Limit the deliverable list so each item stays visible."},"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2026-em"],"rawText":"Partnered with Backend and DevOps teams to deliver secure API integrations, CI/CD pipelines, containerized deployments, and cloud-native solutions using Docker."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — bullet — u-emk-perf-2026 (WEAK)', 'software_engineering', 'lead', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-emk-perf-2026","ingestionVersion":"operator_cv_ingestion_v1","kind":"anti_pattern_example","unitId":"u-emk-perf-2026","quality":"WEAK","contentType":"bullet","dimensionIds":["experience_quality","redundancy_noise"],"evaluation":"Seven improvement areas in one sentence — performance, monitoring, observability, accessibility, standards, tech debt, release quality. When one bullet claims everything, the reader believes nothing specifically. No observable for any of the seven.","reviewFlagIds":[],"reusable":{"contentClass":["LANGUAGE_PATTERN"],"patternText":"Improved [area 1], [area 2], [area 3], [area 4], and [area 5] using [tools] while [area 6] and [area 7].","lesson":"The everything-bullet: past ~three claims, each additional area subtracts credibility. Split into per-area bullets with one observable each, or pick the strongest and cut the rest."},"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2026-em"],"rawText":"Improved application performance, monitoring, observability, accessibility, and engineering standards using Dynatrace and Countly while reducing technical debt and improving release quality."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — bullet — u-emk-java-150 (WEAK)', 'software_engineering', 'lead', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-emk-java-150","ingestionVersion":"operator_cv_ingestion_v1","kind":"anti_pattern_example","unitId":"u-emk-java-150","quality":"WEAK","contentType":"bullet","dimensionIds":["evidence_specificity","achievement_impact"],"evaluation":"'AI-driven IT integrations' is triple-abstracted jargon naming nothing buildable, and the tail carries the mutated satisfaction-by-150% claim. Compare u-emk-revamp-2023, where the same underlying work is described with a real product and a countable metric.","reviewFlagIds":["flag-satisfaction-150"],"reusable":{"contentClass":["LANGUAGE_PATTERN"],"patternText":"Re-engineered [vague platforms] using [languages], implementing [buzzword]-driven [abstraction] that increased [abstract feeling] by [suspicious %].","lesson":"Jargon stacks ('AI-driven IT integrations') plus an abstract percentage is the shape of an inflated bullet. The fix is always the same: name the actual thing built and the actual thing counted."},"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2025-mgmt-a","opcv-2025-mgmt-b","opcv-2025-arch-a","opcv-2025-arch-b"],"rawText":"Re-engineered core digital platforms using Java and TypeScript, implementing AI-driven IT integrations that increased customer satisfaction by 150%."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — technical — u-emk-k8s (ACCEPTABLE)', 'software_engineering', 'lead', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-emk-k8s","ingestionVersion":"operator_cv_ingestion_v1","kind":"cv_unit","unitId":"u-emk-k8s","quality":"ACCEPTABLE","contentType":"technical","dimensionIds":["experience_quality","evidence_specificity"],"evaluation":"Concrete deployment work with a regulatory constraint named — the constraint is substantive evidence in a banking context (per the banking industry pattern). 'Seamless' is filler; 'ensuring high availability' asserts rather than shows.","reviewFlagIds":[],"reusable":{"contentClass":["STRUCTURAL_PATTERN"],"patternText":"Deployed [systems] on [platform], meeting [named regulatory/operational constraint].","lesson":"In regulated industries, naming the compliance framework is real evidence, not filler — regulatory constraints are substantive context (banking-industry pattern)."},"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2025-mgmt-a","opcv-2025-mgmt-b","opcv-2025-arch-a","opcv-2025-arch-b"],"rawText":"Orchestrated the deployment of merchant portals and app services on Kubernetes, ensuring high availability and seamless scaling in line with SAMA frameworks."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — leadership — u-mon-innovation-2026 (STRONG)', 'engineering_leadership', 'manager', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-mon-innovation-2026","ingestionVersion":"operator_cv_ingestion_v1","kind":"cv_unit","unitId":"u-mon-innovation-2026","quality":"STRONG","contentType":"leadership","dimensionIds":["leadership_ownership","seniority_alignment","experience_quality"],"evaluation":"Manager-altitude remit statement: what the role transforms (ideas → production products), for whom, judged by what. No metric and none owed — this is a scope-setting bullet. Register matches the claimed level exactly.","reviewFlagIds":[],"reusable":{"contentClass":["STRUCTURAL_PATTERN"],"patternText":"Lead [function] for [portfolio/beneficiary], turning [input state] into [output state] with a focus on [quality criteria].","lesson":"A manager role should open with a remit bullet: the transformation owned ('turning X into Y') at portfolio altitude — before any individual project detail."},"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2026-em"],"rawText":"Lead engineering efforts for startups and digital innovation initiatives, turning early-stage ideas into production-ready web and mobile products with a strong focus on scalability, maintainability, and product quality."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — leadership — u-mon-direction-2026 (STRONG)', 'engineering_leadership', 'manager', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-mon-direction-2026","ingestionVersion":"operator_cv_ingestion_v1","kind":"cv_unit","unitId":"u-mon-direction-2026","quality":"STRONG","contentType":"leadership","dimensionIds":["leadership_ownership"],"evaluation":"The three things a manager owns (direction, standards, delivery plans) plus the full stakeholder surface — precisely the manager-seniority expectations from the seniority model, stated without inflation.","reviewFlagIds":[],"reusable":{"contentClass":["STRUCTURAL_PATTERN"],"patternText":"Define [direction artifact], [standards artifact], and [planning artifact] while working with [stakeholder functions] to deliver [outcome quality].","lesson":"Manager leadership is legible as owned artifacts — direction, standards, plans — plus the stakeholder surface they cross. No adjectives required."},"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2026-em"],"rawText":"Define technical direction, engineering standards, and delivery plans while working closely with Product, Design, Backend, QA, and DevOps teams to deliver secure, high-performing solutions."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — technical — u-mon-arch-review-2026 (ACCEPTABLE)', 'engineering_leadership', 'manager', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-mon-arch-review-2026","ingestionVersion":"operator_cv_ingestion_v1","kind":"cv_unit","unitId":"u-mon-arch-review-2026","quality":"ACCEPTABLE","contentType":"technical","dimensionIds":["experience_quality","seniority_alignment"],"evaluation":"Shows the manager stays technically credible (reviews, not builds — correct altitude). List-heavy: five review areas + four technologies in one sentence approaches the everything-bullet.","reviewFlagIds":[],"reusable":{"contentClass":["STRUCTURAL_PATTERN"],"patternText":"Review [architecture areas] , collaborating with [teams] on solutions using [core stack].","lesson":"At manager level, 'review' and 'guide' are the honest technical verbs — claiming hands-on building at this altitude would misalign seniority. Keep the list short."},"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2026-em"],"rawText":"Review system architecture, microservices designs, REST API integrations, event-driven workflows, and cloud deployment strategies, collaborating with engineering teams on solutions leveraging PostgreSQL, Redis, Kafka, and Kubernetes."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — achievement — u-mon-strapi-60 (ACCEPTABLE)', 'engineering_leadership', 'manager', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-mon-strapi-60","ingestionVersion":"operator_cv_ingestion_v1","kind":"cv_unit","unitId":"u-mon-strapi-60","quality":"ACCEPTABLE","contentType":"achievement","dimensionIds":["achievement_impact"],"evaluation":"Tool + purpose + measured reduction is a good shape; but the same claim appears elsewhere as 80% (flag-strapi-60-vs-80), so neither number may be taught or reused until the operator confirms which is real.","reviewFlagIds":["flag-strapi-60-vs-80"],"reusable":{"contentClass":["STRUCTURAL_PATTERN"],"patternText":"Integrated [tools] for [operational purpose], reducing [manual process] by [verified amount] and enabling [capability].","lesson":"Automation bullets are strongest as tool + purpose + measured reduction — but a metric that varies across your own document versions is a metric you don't actually have yet."},"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2024-em"],"rawText":"Integrated Strapi CMS and NocoDB for streamlined internal operations, reducing manual data handling by 60% and enabling scalable, low-code content management."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — achievement — u-mon-strapi-80 (ACCEPTABLE)', 'engineering_leadership', 'manager', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-mon-strapi-80","ingestionVersion":"operator_cv_ingestion_v1","kind":"cv_unit","unitId":"u-mon-strapi-80","quality":"ACCEPTABLE","contentType":"achievement","dimensionIds":["achievement_impact","evidence_specificity"],"evaluation":"Same underlying work as u-mon-strapi-60 with a different figure (80% vs 60%) and a vaguer mechanism ('automated IT integration'). The conflict is the finding; no pattern is extracted from this variant to avoid teaching either number.","reviewFlagIds":["flag-strapi-60-vs-80"],"reusable":null,"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2025-mgmt-a","opcv-2025-mgmt-b","opcv-2025-arch-a","opcv-2025-arch-b"],"rawText":"Defined and implemented engineering standards using Strapi and NocoDB, reducing manual data handling by 80% through automated IT integration and lifecycle management."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — project — u-mon-metabase (ACCEPTABLE)', 'engineering_leadership', 'manager', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-mon-metabase","ingestionVersion":"operator_cv_ingestion_v1","kind":"cv_unit","unitId":"u-mon-metabase","quality":"ACCEPTABLE","contentType":"project","dimensionIds":["experience_quality","evidence_specificity"],"evaluation":"Two named, concrete artifacts (a data dictionary, an analytics layer) with an organizational purpose — good internal-system shape. 'Ensure integrity/consistency' asserts the goal rather than an observed change.","reviewFlagIds":[],"reusable":{"contentClass":["STRUCTURAL_PATTERN"],"patternText":"Established [named internal artifact] and [capability] via [tool] to [organizational purpose].","lesson":"Internal-systems work becomes credible when the artifact has a name and an organizational customer; the outcome can be a purpose when no honest measurement exists."},"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2024-em","opcv-2025-mgmt-a","opcv-2025-mgmt-b","opcv-2025-arch-a","opcv-2025-arch-b"],"rawText":"Established a Unified Data Dictionary and real-time analytics via Metabase to ensure data integrity and architectural consistency across the organization."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — bullet — u-mon-compliance (WEAK)', 'engineering_leadership', 'manager', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-mon-compliance","ingestionVersion":"operator_cv_ingestion_v1","kind":"anti_pattern_example","unitId":"u-mon-compliance","quality":"WEAK","contentType":"bullet","dimensionIds":["evidence_specificity","language_quality"],"evaluation":"Three abstractions chained ('stakeholders', 'roadmaps', 'business goals') with zero nouns a reader could probe, capped by '100% regulatory compliance' — an absolute with no audit behind it. Sounds executive, says nothing.","reviewFlagIds":["flag-compliance-100"],"reusable":{"contentClass":["LANGUAGE_PATTERN"],"patternText":"Partner with [generic stakeholders] to align [generic artifact] with [generic goals] while ensuring 100% [absolute claim].","lesson":"Fake executive tone: chained abstractions plus an absolute percentage. Real strategic bullets survive the question 'which stakeholders, which decision, what happened?'"},"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2024-em","opcv-2025-mgmt-a","opcv-2025-mgmt-b","opcv-2025-arch-a","opcv-2025-arch-b"],"rawText":"Partner with cross-functional stakeholders to align technical roadmaps with business goals while ensuring 100% regulatory compliance."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — project — u-mon-revamp-2024 (ACCEPTABLE)', 'engineering_leadership', 'manager', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-mon-revamp-2024","ingestionVersion":"operator_cv_ingestion_v1","kind":"cv_unit","unitId":"u-mon-revamp-2024","quality":"ACCEPTABLE","contentType":"project","dimensionIds":["experience_quality","leadership_ownership"],"evaluation":"End-to-end ownership of a platform revamp with concrete stack. 'Elevate user experience and performance' is asserted, not evidenced; at manager level the bullet also under-plays the team dimension (who did the person lead?).","reviewFlagIds":[],"reusable":{"contentClass":["STRUCTURAL_PATTERN"],"patternText":"Led the end-to-end revamp of [platform scope], using [technologies] to [improvement purpose] across [surfaces].","lesson":"'End-to-end' earns its place when the scope is named. At manager level, add the team dimension — a revamp bullet without people led reads as an IC bullet."},"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2024-em"],"rawText":"Led the end-to-end revamp of Monshaat's digital platforms, using React Native, Next.js, and Figma to elevate user experience and performance across web and mobile."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — project — u-mon-sprints-2024 (ACCEPTABLE)', 'engineering_leadership', 'manager', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-mon-sprints-2024","ingestionVersion":"operator_cv_ingestion_v1","kind":"cv_unit","unitId":"u-mon-sprints-2024","quality":"ACCEPTABLE","contentType":"project","dimensionIds":["experience_quality","seniority_alignment"],"evaluation":"Concrete deliverable (a named website shipped) but the framing is activity-level (sprints, ceremonies) for a manager document — process vocabulary carrying weight that outcomes should carry. Superseded in v5 by the remit-level u-mon-innovation-2026.","reviewFlagIds":[],"reusable":{"contentClass":["STRUCTURAL_PATTERN"],"patternText":"Led [process ceremonies] to deliver [deliverable], aligning development with [goals] and improving [process quality] through [methodology].","lesson":"Process vocabulary (sprints, Agile, ceremonies) describes how you worked, not what changed. As seniority rises, the same work should be re-framed from activities to remit."},"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2024-em"],"rawText":"Led cross-functional sprints to deliver the Innovation Center website, aligning development with strategic goals and improving delivery efficiency through Agile practices."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — leadership — u-mun-team (STRONG)', 'engineering_leadership', 'manager', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-mun-team","ingestionVersion":"operator_cv_ingestion_v1","kind":"cv_unit","unitId":"u-mun-team","quality":"STRONG","contentType":"leadership","dimensionIds":["leadership_ownership","experience_quality"],"evaluation":"Team + deliverable + technical scope in one clean line: led whom, to ship what, across which layers. The manager-bullet skeleton with no wasted words.","reviewFlagIds":[],"reusable":{"contentClass":["STRUCTURAL_PATTERN"],"patternText":"Led a cross-functional engineering team to deliver [product], overseeing [layer 1], [layer 2], and [layer 3].","lesson":"LEADERSHIP + TEAM + DELIVERY + SCOPE: the minimal complete manager bullet — who was led, what shipped, what surface was overseen."},"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2024-em"],"rawText":"Led a cross-functional engineering team to deliver Munaseb's fintech platform, overseeing frontend, backend, and service integrations."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — technical — u-mun-integrations (STRONG)', 'engineering_leadership', 'manager', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-mun-integrations","ingestionVersion":"operator_cv_ingestion_v1","kind":"cv_unit","unitId":"u-mun-integrations","quality":"STRONG","contentType":"technical","dimensionIds":["evidence_specificity","experience_quality"],"evaluation":"Short and dense: two ownership verbs (architected AND launched — design through delivery), a real constraint (regulation-compliant), and three named external integrations any fintech reader can verify the difficulty of. High evidence texture, no metric needed.","reviewFlagIds":[],"reusable":{"contentClass":["STRUCTURAL_PATTERN"],"patternText":"Architected and launched a [constraint-bearing] system integrated with [named external system 1], [2], and [3].","lesson":"Named third-party integrations are self-authenticating evidence — a reader who knows the domain knows exactly what integrating them takes. Verb pairs like 'architected and launched' compactly claim design-through-delivery."},"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2024-em"],"rawText":"Architected and launched a secure, regulation-compliant system integrated with Simah, Nafath, and Yaqeen."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — project — u-mun-mvp (ACCEPTABLE)', 'engineering_leadership', 'manager', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-mun-mvp","ingestionVersion":"operator_cv_ingestion_v1","kind":"cv_unit","unitId":"u-mun-mvp","quality":"ACCEPTABLE","contentType":"project","dimensionIds":["experience_quality"],"evaluation":"Founder-facing influence is a real startup-context signal; 'shape product direction' and 'successful MVP' are soft ('successful' self-graded). Delivery fact is real (the MVP shipped).","reviewFlagIds":[],"reusable":{"contentClass":["STRUCTURAL_PATTERN"],"patternText":"Worked directly with [founders/decision-makers] to shape [product decisions] and deliver [milestone].","lesson":"In startup contexts, proximity to founders and shipped milestones are the relevant scope signals — but let the milestone speak; 'successful' is the reader's judgment to make."},"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2024-em"],"rawText":"Collaborated closely with founders and stakeholders to shape product direction and deliver a successful MVP."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — leadership — u-twq-team (ACCEPTABLE)', 'engineering_leadership', 'lead', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-twq-team","ingestionVersion":"operator_cv_ingestion_v1","kind":"cv_unit","unitId":"u-twq-team","quality":"ACCEPTABLE","contentType":"leadership","dimensionIds":["leadership_ownership","experience_quality"],"evaluation":"Team mode (remote-first) + concrete systems + stack. No team size, no outcome yet (role listed as Present) — acceptable for an in-progress engagement.","reviewFlagIds":[],"reusable":{"contentClass":["STRUCTURAL_PATTERN"],"patternText":"Leading a [team mode] team to build [system 1] and [system 2] using [stack].","lesson":"Working-mode context ('remote-first') is legitimate scope information — it tells the reader what kind of leadership was required."},"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2024-em"],"rawText":"Leading a remote-first team to build merchant onboarding systems and internal dashboards using React, Next.js, and GitLab CI/CD."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — bullet — u-twq-standups (WEAK)', 'engineering_leadership', 'lead', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-twq-standups","ingestionVersion":"operator_cv_ingestion_v1","kind":"anti_pattern_example","unitId":"u-twq-standups","quality":"WEAK","contentType":"bullet","dimensionIds":["content_prioritization","seniority_alignment"],"evaluation":"Running standups is table stakes, not an achievement — task-level minutiae on a leadership document. Space this line occupies is space the role's real outcomes don't get.","reviewFlagIds":[],"reusable":{"contentClass":["LANGUAGE_PATTERN"],"patternText":"Implemented [routine process ceremony] to improve [generic team quality].","lesson":"If a bullet describes something every competent holder of the role does by default (standups, code reviews existing at all), it is prioritization noise — cut it and spend the line on an outcome."},"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2024-em"],"rawText":"Implemented structured workflows, including Slack-based standups to improve team coordination and delivery speed."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — leadership — u-comp-mentoring (STRONG)', 'engineering_leadership', 'manager', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-comp-mentoring","ingestionVersion":"operator_cv_ingestion_v1","kind":"cv_unit","unitId":"u-comp-mentoring","quality":"STRONG","contentType":"leadership","dimensionIds":["leadership_ownership","evidence_specificity"],"evaluation":"People-leadership with explicit scope (a stated mentee count) and the concrete mechanisms (1:1s, reviews, retention). The one competency line in all five versions that quantifies people scope.","reviewFlagIds":[],"reusable":{"contentClass":["STRUCTURAL_PATTERN"],"patternText":"People development: mentoring [N]+ engineers through [mechanism 1], [mechanism 2], and [mechanism 3].","lesson":"People-leadership claims become checkable the moment head-count scope and the actual mechanisms are stated — 'mentoring N engineers via 1:1s and reviews' beats any amount of 'passionate about growing teams'."},"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2025-mgmt-a","opcv-2025-mgmt-b"],"rawText":"Leadership & People Development: Mentoring 20+ engineers, 1:1 coaching, performance reviews, and talent retention."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — technical — u-comp-openai-2023 (WEAK)', 'software_engineering', 'lead', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-comp-openai-2023","ingestionVersion":"operator_cv_ingestion_v1","kind":"anti_pattern_example","unitId":"u-comp-openai-2023","quality":"WEAK","contentType":"technical","dimensionIds":["language_quality","evidence_specificity"],"evaluation":"Real, differentiating work (an LLM API integration in production fintech, early) buried under broken phrasing — 'the applying product process' and 'experience journeys' force rereading. A strong fact defeated by language quality.","reviewFlagIds":[],"reusable":{"contentClass":["LANGUAGE_PATTERN"],"patternText":"Integrated [notable API/technology] into [product] to [garbled purpose clause].","lesson":"A genuinely differentiating fact can be sunk purely by sentence mechanics — language-quality findings matter most on the bullets that matter most."},"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2023-lead"],"rawText":"Open AI. Integrating and developing OpenAI's API into the emkan app to enhance the applying product process and improve customer experience journeys."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — award — u-award-waed (ACCEPTABLE)', 'any', 'entry', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-award-waed","ingestionVersion":"operator_cv_ingestion_v1","kind":"cv_unit","unitId":"u-award-waed","quality":"ACCEPTABLE","contentType":"award","dimensionIds":["evidence_specificity","content_prioritization"],"evaluation":"Model award line: rank + named competition + prize scale + date. All five versions keep it — correctly, since a national first place stays load-bearing. (The operator's specific awards are facts, never reusable content.)","reviewFlagIds":[],"reusable":{"contentClass":["STRUCTURAL_PATTERN"],"patternText":"[Rank]: [Named competition/issuer] ([prize or scale]). [Date]","lesson":"Award lines carry weight through rank + issuer + scale + date. Undated, unranked award mentions ('won multiple awards') spend the same space for a fraction of the credibility."},"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2023-lead","opcv-2024-em","opcv-2025-mgmt-a","opcv-2025-mgmt-b","opcv-2025-arch-a","opcv-2025-arch-b","opcv-2026-em"],"rawText":"1st Place: Aramco's Wa'ed Programming Competition (100k Award). Nov 2018"}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — career_progression — u-edu-degree (ACCEPTABLE)', 'any', 'entry', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-edu-degree","ingestionVersion":"operator_cv_ingestion_v1","kind":"cv_unit","unitId":"u-edu-degree","quality":"ACCEPTABLE","contentType":"career_progression","dimensionIds":["content_prioritization"],"evaluation":"Degree + distinction + the reason for the distinction. Wordy ('with honors by the college's Dean for my participation and achievements in winning') and, on a 9-year manager CV, education detail at this length is a prioritization question. Kept as fact; no reusable pattern extracted beyond what the prioritization rubric already teaches.","reviewFlagIds":[],"reusable":null,"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2023-lead","opcv-2024-em","opcv-2025-mgmt-a","opcv-2025-mgmt-b","opcv-2025-arch-a","opcv-2025-arch-b","opcv-2026-em"],"rawText":"B.A. Degree - Advanced Knowledge of Algorithms and Problem Solving. Earned a B.A. Degree in Computer Science from King Faisal University, with honors by the college's Dean for my participation and achievements in winning multiple programming competitions."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — bullet — u-sum-breadth-2023 (DO_NOT_REUSE)', 'engineering_leadership', 'lead', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-sum-breadth-2023","ingestionVersion":"operator_cv_ingestion_v1","kind":"cv_unit","unitId":"u-sum-breadth-2023","quality":"DO_NOT_REUSE","contentType":"bullet","dimensionIds":["evidence_specificity"],"evaluation":"Unverifiable percentage + unmeasurable claim ('substantial profitability') + maximal vagueness ('various development domains'). Nothing here is a fact, a pattern, or even a clean anti-pattern beyond what ap-unverifiable-metric already teaches. Excluded entirely.","reviewFlagIds":["flag-quality-95"],"reusable":null,"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2023-lead"],"rawText":"…enhancing quality by 95% and driving substantial profitability across various development domains."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Operator CV — bullet — u-comp-swiftui-2024 (DO_NOT_REUSE)', 'software_engineering', 'manager', 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:unit:u-comp-swiftui-2024","ingestionVersion":"operator_cv_ingestion_v1","kind":"cv_unit","unitId":"u-comp-swiftui-2024","quality":"DO_NOT_REUSE","contentType":"bullet","dimensionIds":["skills_relevance"],"evaluation":"Headline names SwiftUI, body demonstrates only React Native/Figma — a skills-relevance mismatch (skill claimed, never evidenced anywhere in any version). Too context-dependent and unsupported to reuse in any direction.","reviewFlagIds":[],"reusable":null,"operatorFact":{"nonReusable":true,"sourceIds":["opcv-2024-em"],"rawText":"Swift UI & React native … Proficient in React Native and Figma, with expertise in designing adaptive, interactive, and scalable user interfaces across Apple platforms."}}$ocv1$::jsonb, 'operator_cv', false, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Pattern — Action + ownership + scope + outcome', null, null, 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:pattern:bp-action-ownership-scope-outcome","ingestionVersion":"operator_cv_ingestion_v1","patternId":"bp-action-ownership-scope-outcome","kind":"reusable_pattern","contentClass":"STRUCTURAL_PATTERN","name":"Action + ownership + scope + outcome","slots":["ACTION","OWNERSHIP","SCOPE","OUTCOME"],"template":"Led the development of [product] using [core technologies], contributing to [verified outcome 1] and [verified outcome 2].","guidance":"The workhorse achievement bullet. 'Contributing to' is the honest attribution verb for team results the person genuinely drove — stronger than overclaiming, more credible than hiding. Outcomes must come from the user's own verified facts; if none exist, ask the missing-evidence question instead of filling the slot.","applicableSeniority":["mid","senior","lead"],"language":"en","dimensionIds":["experience_quality","achievement_impact"],"derivedFromUnitIds":["u-arj-led-2026"],"patternKind":"bullet"}$ocv1$::jsonb, 'operator_cv', true, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Pattern — Outcome first, then mechanism', null, null, 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:pattern:bp-outcome-mechanism-tools","ingestionVersion":"operator_cv_ingestion_v1","patternId":"bp-outcome-mechanism-tools","kind":"reusable_pattern","contentClass":"STRUCTURAL_PATTERN","name":"Outcome first, then mechanism","slots":["OUTCOME","MECHANISM","TOOLS"],"template":"Improved [measured result] through the development of [product/system] using [tools].","guidance":"Leading with the result suits bullets whose metric is the headline. Only usable when the result is a real measured fact; an assertion ('improved user experience') in the outcome slot collapses the pattern.","applicableSeniority":["entry","mid","senior","lead"],"language":"en","dimensionIds":["achievement_impact"],"derivedFromUnitIds":["u-arj-downloads-2023"],"patternKind":"bullet"}$ocv1$::jsonb, 'operator_cv', true, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Pattern — Mechanism + named system + purpose (no metric needed)', null, null, 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:pattern:bp-mechanism-named-system-purpose","ingestionVersion":"operator_cv_ingestion_v1","patternId":"bp-mechanism-named-system-purpose","kind":"reusable_pattern","contentClass":"STRUCTURAL_PATTERN","name":"Mechanism + named system + purpose (no metric needed)","slots":["ACTION","MECHANISM BUILT","NAMED EXTERNAL SYSTEM","PURPOSE"],"template":"Optimized [system area] by developing [the thing you built] to interface with [named external system] for [business purpose].","guidance":"The metric-free strong bullet: credibility comes from the concrete artifact built and the named system it talks to. Use when honest numbers don't exist — a named mechanism beats an invented percentage every time.","applicableSeniority":["mid","senior","lead"],"language":"en","dimensionIds":["experience_quality","evidence_specificity"],"derivedFromUnitIds":["u-arj-middleware","u-mun-integrations"],"patternKind":"bullet"}$ocv1$::jsonb, 'operator_cv', true, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Pattern — Leadership + team + delivery + scope', null, null, 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:pattern:bp-leadership-team-delivery-scope","ingestionVersion":"operator_cv_ingestion_v1","patternId":"bp-leadership-team-delivery-scope","kind":"reusable_pattern","contentClass":"STRUCTURAL_PATTERN","name":"Leadership + team + delivery + scope","slots":["LEADERSHIP","TEAM","DELIVERABLE","TECHNICAL SCOPE"],"template":"Led a cross-functional engineering team to deliver [product], overseeing [area 1], [area 2], and [area 3].","guidance":"The minimal complete manager bullet: who was led, what shipped, what surface was overseen. Team size strengthens it when the user can state one — ask, never estimate.","applicableSeniority":["lead","manager","director"],"language":"en","dimensionIds":["leadership_ownership","experience_quality"],"derivedFromUnitIds":["u-mun-team"],"patternKind":"bullet"}$ocv1$::jsonb, 'operator_cv', true, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Pattern — Practice establishment (senior influence without reports)', null, null, 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:pattern:bp-practice-establishment","ingestionVersion":"operator_cv_ingestion_v1","patternId":"bp-practice-establishment","kind":"reusable_pattern","contentClass":"STRUCTURAL_PATTERN","name":"Practice establishment (senior influence without reports)","slots":["ESTABLISHED","PRACTICES","QUALITATIVE PURPOSE"],"template":"Established [architecture/practice 1], [practice 2], and [practice 3] to improve [qualitative outcome].","guidance":"Shows senior-level influence without people management: practices others then work within. The outcome is legitimately qualitative — do not decorate maintainability with a number.","applicableSeniority":["senior","lead"],"language":"en","dimensionIds":["experience_quality","leadership_ownership"],"derivedFromUnitIds":["u-arj-frontarch-2026"],"patternKind":"bullet"}$ocv1$::jsonb, 'operator_cv', true, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Pattern — Remit transformation (manager altitude)', null, null, 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:pattern:bp-remit-transformation","ingestionVersion":"operator_cv_ingestion_v1","patternId":"bp-remit-transformation","kind":"reusable_pattern","contentClass":"STRUCTURAL_PATTERN","name":"Remit transformation (manager altitude)","slots":["REMIT","INPUT STATE","OUTPUT STATE","QUALITY CRITERIA"],"template":"Lead [function] for [portfolio/beneficiary], turning [input state] into [output state] with a focus on [quality criteria].","guidance":"A manager role's opening bullet: the transformation owned, at portfolio altitude, before any project detail. If a document at manager level has no bullet at this altitude, that absence is itself the finding.","applicableSeniority":["manager","director","executive"],"language":"en","dimensionIds":["leadership_ownership","seniority_alignment"],"derivedFromUnitIds":["u-mon-innovation-2026"],"patternKind":"bullet"}$ocv1$::jsonb, 'operator_cv', true, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Pattern — Manager summary: identity → technical depth → leadership', null, null, 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:pattern:sp-manager-three-sentence","ingestionVersion":"operator_cv_ingestion_v1","patternId":"sp-manager-three-sentence","kind":"reusable_pattern","contentClass":"STRUCTURAL_PATTERN","name":"Manager summary: identity → technical depth → leadership","slots":["IDENTITY + DOMAIN + SECTORS","TECHNICAL AREAS","COLLABORATION + LEADERSHIP SIGNAL"],"template":"[Role] with [N]+ years leading [team type] in [domain], delivering [platform type] across [sectors]. Experienced in [2–3 technical areas]. Strong background [collaboration surface] while [leadership signal] and [strategic signal].","guidance":"Three sentences, three jobs: who at what level in what domain; what technical ground is covered (trim to what the target role cares about); how they lead. No numbers unless verified, no 'seeking' clause, no 'proven track record'.","applicableSeniority":["lead","manager","director"],"language":"en","dimensionIds":["professional_summary","positioning"],"derivedFromUnitIds":["u-sum-2026"],"patternKind":"summary"}$ocv1$::jsonb, 'operator_cv', true, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Pattern — Per-target specialization variants', null, null, 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:pattern:sp-specialization-variant","ingestionVersion":"operator_cv_ingestion_v1","patternId":"sp-specialization-variant","kind":"reusable_pattern","contentClass":"STRUCTURAL_PATTERN","name":"Per-target specialization variants","slots":["STABLE SKELETON","SWAPPABLE SPECIALIZATION SLOT"],"template":"[Identical truthful summary skeleton], with the specialization slot ([e.g. payments / architecture / people leadership]) swapped to match each target role.","guidance":"Maintaining summary variants that differ only in the emphasized specialization is legitimate targeting — the facts never change, only which true thing leads. Distinct from rewriting the self per application, which produces contradiction.","applicableSeniority":["mid","senior","lead","manager","director","executive"],"language":"en","dimensionIds":["professional_summary","target_role_alignment"],"derivedFromUnitIds":["u-sum-mgmt","u-sum-arch"],"patternKind":"summary"}$ocv1$::jsonb, 'operator_cv', true, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Pattern — IC summary: identity + domain + one proof point', null, null, 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:pattern:sp-ic-identity-domain","ingestionVersion":"operator_cv_ingestion_v1","patternId":"sp-ic-identity-domain","kind":"reusable_pattern","contentClass":"STRUCTURAL_PATTERN","name":"IC summary: identity + domain + one proof point","slots":["ROLE + YEARS","DOMAIN/SPECIALIZATION","ONE CHECKABLE CLAIM"],"template":"[Role], [N] years in [domain], specialized in [specific area]; [one distinctive, checkable claim from the experience section].","guidance":"For individual contributors: identity and specialization in one breath plus a single claim the experience section can prove. Kept deliberately shorter than the manager shape — an entry/mid summary that talks strategy misaligns seniority.","applicableSeniority":["entry","mid","senior"],"language":"en","dimensionIds":["professional_summary","seniority_alignment"],"derivedFromUnitIds":["u-sum-2026"],"patternKind":"summary"}$ocv1$::jsonb, 'operator_cv', true, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Pattern — Integration project: constraint + named systems', null, null, 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:pattern:pp-integration-project","ingestionVersion":"operator_cv_ingestion_v1","patternId":"pp-integration-project","kind":"reusable_pattern","contentClass":"STRUCTURAL_PATTERN","name":"Integration project: constraint + named systems","slots":["ACTION PAIR","CONSTRAINT","NAMED SYSTEMS"],"template":"Architected and launched a [constraint-bearing, e.g. regulation-compliant] system integrated with [named external system 1], [2], and [3].","guidance":"Named third-party systems are self-authenticating: readers who know the domain know what integrating them takes. Verb pairs ('architected and launched') compactly claim design-through-delivery. Works for fintech, government, healthcare — anywhere integrations are gatekept.","applicableSeniority":["senior","lead","manager"],"language":"en","dimensionIds":["evidence_specificity","experience_quality"],"derivedFromUnitIds":["u-mun-integrations"],"patternKind":"project"}$ocv1$::jsonb, 'operator_cv', true, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Pattern — Internal system: named artifact + organizational customer', null, null, 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:pattern:pp-internal-system","ingestionVersion":"operator_cv_ingestion_v1","patternId":"pp-internal-system","kind":"reusable_pattern","contentClass":"STRUCTURAL_PATTERN","name":"Internal system: named artifact + organizational customer","slots":["NAMED ARTIFACT","CAPABILITY","TOOL","ORGANIZATIONAL PURPOSE"],"template":"Established [named internal artifact] and [capability] via [tool] to [organizational purpose].","guidance":"Internal/back-office work becomes credible when the artifact has a name and an internal customer. The outcome may be a purpose when no honest measurement exists — a real purpose beats a fake percentage.","applicableSeniority":["mid","senior","lead","manager"],"language":"en","dimensionIds":["experience_quality","evidence_specificity"],"derivedFromUnitIds":["u-mon-metabase"],"patternKind":"project"}$ocv1$::jsonb, 'operator_cv', true, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Pattern — Platform revamp / modernization', null, null, 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:pattern:pp-platform-revamp","ingestionVersion":"operator_cv_ingestion_v1","patternId":"pp-platform-revamp","kind":"reusable_pattern","contentClass":"STRUCTURAL_PATTERN","name":"Platform revamp / modernization","slots":["END-TO-END OWNERSHIP","NAMED SCOPE","STACK","PURPOSE","SURFACES"],"template":"Led the end-to-end revamp of [platform scope], using [technologies] to [improvement purpose] across [surfaces].","guidance":"'End-to-end' earns its place only when the scope is named. On leadership documents, add the team dimension — a revamp with no people led reads as an IC project. Outcome slot: verified facts only, else ask.","applicableSeniority":["senior","lead","manager"],"language":"en","dimensionIds":["experience_quality","leadership_ownership"],"derivedFromUnitIds":["u-mon-revamp-2024","u-emk-revamp-2023"],"patternKind":"project"}$ocv1$::jsonb, 'operator_cv', true, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Pattern — MVP / startup delivery', null, null, 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:pattern:pp-mvp-startup","ingestionVersion":"operator_cv_ingestion_v1","patternId":"pp-mvp-startup","kind":"reusable_pattern","contentClass":"STRUCTURAL_PATTERN","name":"MVP / startup delivery","slots":["DECISION-MAKER PROXIMITY","PRODUCT DECISIONS","MILESTONE"],"template":"Worked directly with [founders/decision-makers] to shape [product decisions] and deliver [milestone].","guidance":"In startup contexts the scope signals are proximity to decision-makers and shipped milestones. Let the milestone speak for itself — 'successful' is the reader's judgment, not the writer's.","applicableSeniority":["senior","lead","manager"],"language":"en","dimensionIds":["experience_quality"],"derivedFromUnitIds":["u-mun-mvp"],"patternKind":"project"}$ocv1$::jsonb, 'operator_cv', true, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Pattern — People development with head-count scope', null, null, 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:pattern:lp-people-development-scope","ingestionVersion":"operator_cv_ingestion_v1","patternId":"lp-people-development-scope","kind":"reusable_pattern","contentClass":"ROLE_GUIDANCE","name":"People development with head-count scope","slots":["MENTEE COUNT","MECHANISMS"],"template":"People development: mentoring [N]+ engineers through [1:1 coaching / performance reviews / progression planning].","guidance":"People-leadership becomes checkable when head-count scope and concrete mechanisms are stated. The count must be the user's own — ask for it; never estimate from role or company size.","applicableSeniority":["lead","manager","director"],"language":"en","dimensionIds":["leadership_ownership","evidence_specificity"],"derivedFromUnitIds":["u-comp-mentoring"],"patternKind":"leadership"}$ocv1$::jsonb, 'operator_cv', true, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Pattern — Leadership as owned artifacts', null, null, 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:pattern:lp-owned-artifacts","ingestionVersion":"operator_cv_ingestion_v1","patternId":"lp-owned-artifacts","kind":"reusable_pattern","contentClass":"ROLE_GUIDANCE","name":"Leadership as owned artifacts","slots":["DIRECTION ARTIFACT","STANDARDS ARTIFACT","PLANNING ARTIFACT","STAKEHOLDER SURFACE"],"template":"Define [technical direction], [engineering standards], and [delivery plans] while working with [stakeholder functions] to deliver [outcome quality].","guidance":"Manager leadership is legible as the artifacts owned — direction, standards, plans — plus the stakeholder surface they cross. This is the shape to reach for when a manager document is all adjectives ('strong leader') and no owned decisions.","applicableSeniority":["manager","director"],"language":"en","dimensionIds":["leadership_ownership"],"derivedFromUnitIds":["u-mon-direction-2026"],"patternKind":"leadership"}$ocv1$::jsonb, 'operator_cv', true, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Pattern — Altitude-honest technical verbs at manager+', null, null, 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:pattern:lp-altitude-review-verbs","ingestionVersion":"operator_cv_ingestion_v1","patternId":"lp-altitude-review-verbs","kind":"reusable_pattern","contentClass":"ROLE_GUIDANCE","name":"Altitude-honest technical verbs at manager+","slots":["REVIEW/GUIDE VERB","ARCHITECTURE AREAS","TEAMS"],"template":"Review [architecture areas], collaborating with [teams] on solutions using [core stack].","guidance":"At manager level and above, 'review', 'guide', and 'direct' are the honest technical verbs; claiming hands-on building misaligns the document's altitude. Keeps technical credibility visible without cosplaying as an IC.","applicableSeniority":["manager","director","executive"],"language":"en","dimensionIds":["seniority_alignment","leadership_ownership"],"derivedFromUnitIds":["u-mon-arch-review-2026"],"patternKind":"leadership"}$ocv1$::jsonb, 'operator_cv', true, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Pattern — Technology belongs inside the action', null, null, 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:pattern:tp-tech-inside-action","ingestionVersion":"operator_cv_ingestion_v1","patternId":"tp-tech-inside-action","kind":"reusable_pattern","contentClass":"LANGUAGE_PATTERN","name":"Technology belongs inside the action","slots":["ACTION","PRODUCT","TECHNOLOGY","USER/BUSINESS PURPOSE"],"template":"Built [product/interface] using [technology] to support [user/business purpose].","guidance":"Technology alone is not an achievement. A technology earns its mention by sitting inside an action that served a purpose — never as a parenthesized dump or a bare list. If the purpose slot can't be filled truthfully, the bullet isn't ready.","applicableSeniority":["entry","mid","senior","lead"],"language":"en","dimensionIds":["experience_quality","skills_relevance"],"derivedFromUnitIds":["u-arj-impl-2023","u-arj-led-2026"],"patternKind":"technical"}$ocv1$::jsonb, 'operator_cv', true, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Pattern — Regulatory constraints are evidence in regulated industries', null, null, 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:pattern:tp-regulated-constraint","ingestionVersion":"operator_cv_ingestion_v1","patternId":"tp-regulated-constraint","kind":"reusable_pattern","contentClass":"ROLE_GUIDANCE","name":"Regulatory constraints are evidence in regulated industries","slots":["DEPLOYMENT/BUILD ACTION","SYSTEMS","NAMED CONSTRAINT"],"template":"Deployed [systems] on [platform], meeting [named regulatory/operational constraint].","guidance":"In banking, government, and health contexts, naming the compliance framework the work satisfied is substantive evidence, not filler — and often the honest substitute for confidential numbers.","applicableSeniority":["mid","senior","lead","manager"],"language":"en","dimensionIds":["evidence_specificity"],"derivedFromUnitIds":["u-emk-k8s"],"patternKind":"technical"}$ocv1$::jsonb, 'operator_cv', true, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Pattern — ''Partnered with'' for genuinely shared work', null, null, 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:pattern:tp-honest-collaboration-verb","ingestionVersion":"operator_cv_ingestion_v1","patternId":"tp-honest-collaboration-verb","kind":"reusable_pattern","contentClass":"LANGUAGE_PATTERN","name":"'Partnered with' for genuinely shared work","slots":["PARTNER VERB","TEAMS","DELIVERABLES"],"template":"Partnered with [teams] to deliver [deliverable 1], [deliverable 2], and [deliverable 3].","guidance":"'Partnered with' is the truthful verb for shared work — more credible than inflating to 'led', more substantive than 'worked closely with' when followed by concrete deliverables. Cap the list at three so each stays visible.","applicableSeniority":["mid","senior","lead"],"language":"en","dimensionIds":["language_quality","experience_quality"],"derivedFromUnitIds":["u-emk-cicd-2026","u-arj-collab-2026"],"patternKind":"technical"}$ocv1$::jsonb, 'operator_cv', true, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Anti-pattern — Parenthesized technology dump', null, null, 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:anti:ap-tech-dump-parens","ingestionVersion":"operator_cv_ingestion_v1","kind":"anti_pattern","antiPatternId":"ap-tech-dump-parens","name":"Parenthesized technology dump","description":"Technologies listed in parentheses, detached from any action.","example":"Implemented and designed the app with extensive knowledge of ([six technologies]).","whyBad":"'With extensive knowledge of' praises the author instead of describing work; the parens make the tools decoration rather than evidence.","detection":"Parenthesized comma lists of 3+ technologies; 'with (extensive) knowledge of'.","dimensionIds":["experience_quality","language_quality"],"derivedFromUnitIds":["u-arj-impl-2023","u-emk-portal-2023"]}$ocv1$::jsonb, 'operator_cv', true, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Anti-pattern — Vapor outcome', null, null, 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:anti:ap-vapor-outcome","ingestionVersion":"operator_cv_ingestion_v1","kind":"anti_pattern","antiPatternId":"ap-vapor-outcome","name":"Vapor outcome","description":"A result clause asserting a feeling instead of a change.","example":"…which led to customer satisfaction. / …delivering new features with improved customer satisfaction.","whyBad":"Unfalsifiable and unmeasured — it asserts an emotion, not an observable. The bullet would be stronger ending at the concrete work.","detection":"Outcome clauses containing satisfaction/happiness/delight with no observable; 'improved user experience' with no evidence.","dimensionIds":["achievement_impact","evidence_specificity"],"derivedFromUnitIds":["u-emk-portal-2023","u-arj-rd-2023"]}$ocv1$::jsonb, 'operator_cv', true, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Anti-pattern — Implausible or mutated metric', null, null, 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:anti:ap-implausible-metric","ingestionVersion":"operator_cv_ingestion_v1","kind":"anti_pattern","antiPatternId":"ap-implausible-metric","name":"Implausible or mutated metric","description":"A percentage attached to something that isn't a quantity, or a metric whose measured noun drifted between edits.","example":"…increasing customer satisfaction by [triple-digit]%.","whyBad":"Satisfaction is not a quantity that can grow by a triple-digit percentage; readers discount every other number in the document once one metric reads as invented. Flag for confirmation — never 'fix' by picking a number.","detection":"Percentages > 100 on abstract nouns; the same figure attached to different nouns across versions; suspiciously uniform round numbers.","dimensionIds":["evidence_specificity","achievement_impact"],"derivedFromUnitIds":["u-emk-portal-2026","u-emk-java-150"]}$ocv1$::jsonb, 'operator_cv', true, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Anti-pattern — Unverifiable quality percentage', null, null, 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:anti:ap-unverifiable-quality-metric","ingestionVersion":"operator_cv_ingestion_v1","kind":"anti_pattern","antiPatternId":"ap-unverifiable-quality-metric","name":"Unverifiable quality percentage","description":"A precise number on an unmeasured abstraction.","example":"…improving platform quality by [N]% / enhancing quality by [N]%.","whyBad":"'Quality' was never measured; the precision is fake. One unverifiable number taxes the credibility of every real one.","detection":"Percentages attached to quality/excellence/efficiency with no named measurement.","dimensionIds":["evidence_specificity"],"derivedFromUnitIds":["u-sum-2023","u-sum-mgmt"]}$ocv1$::jsonb, 'operator_cv', true, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Anti-pattern — The ''seeking'' objective', null, null, 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:anti:ap-seeking-objective","ingestionVersion":"operator_cv_ingestion_v1","kind":"anti_pattern","antiPatternId":"ap-seeking-objective","name":"The 'seeking' objective","description":"Summary ends by asking rather than offering.","example":"Seeking to leverage my expertise to enhance business operations…","whyBad":"Spends prime first-page space on what the candidate wants instead of what the reader gets; reads junior at every seniority.","detection":"'Seeking', 'looking for an opportunity', 'to utilize my skills' in summaries.","dimensionIds":["professional_summary","content_prioritization"],"derivedFromUnitIds":["u-sum-2023","u-sum-2024em"]}$ocv1$::jsonb, 'operator_cv', true, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Anti-pattern — The everything-bullet', null, null, 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:anti:ap-everything-bullet","ingestionVersion":"operator_cv_ingestion_v1","kind":"anti_pattern","antiPatternId":"ap-everything-bullet","name":"The everything-bullet","description":"One bullet claiming five-plus improvement areas.","example":"Improved performance, monitoring, observability, accessibility, and standards while reducing technical debt and improving release quality.","whyBad":"Past ~three claims, each additional area subtracts credibility — the reader believes nothing specifically. Also the shape AI assistants produce when asked to 'make it comprehensive'.","detection":"Bullets with 4+ improvement claims and zero observables.","dimensionIds":["experience_quality","redundancy_noise"],"derivedFromUnitIds":["u-emk-perf-2026"]}$ocv1$::jsonb, 'operator_cv', true, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Anti-pattern — Fake executive tone', null, null, 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:anti:ap-fake-executive-tone","ingestionVersion":"operator_cv_ingestion_v1","kind":"anti_pattern","antiPatternId":"ap-fake-executive-tone","name":"Fake executive tone","description":"Chained abstractions with an absolute claim.","example":"Partner with cross-functional stakeholders to align technical roadmaps with business goals while ensuring 100% compliance.","whyBad":"Sounds strategic, says nothing checkable: no named stakeholder, decision, or observable. Real strategic bullets survive 'which stakeholders, which decision, what happened?'","detection":"Sentences whose every noun is abstract (stakeholders/roadmaps/goals/alignment) plus absolutes (100%, 'all', 'fully').","dimensionIds":["evidence_specificity","language_quality"],"derivedFromUnitIds":["u-mon-compliance"]}$ocv1$::jsonb, 'operator_cv', true, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Anti-pattern — Participation dressed as leadership', null, null, 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:anti:ap-participation-as-leadership","ingestionVersion":"operator_cv_ingestion_v1","kind":"anti_pattern","antiPatternId":"ap-participation-as-leadership","name":"Participation dressed as leadership","description":"'Led' or a department claim without scope or owned decisions.","example":"Led the department to focus on [theme], delivering [generic outcome].","whyBad":"Leadership claims without team size, remit, or a checkable result read as attendance. Downgrades trust in the document's real leadership content.","detection":"'Led' + no scope + no outcome; leadership adjectives with no owned decision anywhere.","dimensionIds":["leadership_ownership","evidence_specificity"],"derivedFromUnitIds":["u-arj-rd-2023"]}$ocv1$::jsonb, 'operator_cv', true, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Anti-pattern — Ceremony minutiae on leadership documents', null, null, 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:anti:ap-ceremony-minutiae","ingestionVersion":"operator_cv_ingestion_v1","kind":"anti_pattern","antiPatternId":"ap-ceremony-minutiae","name":"Ceremony minutiae on leadership documents","description":"Table-stakes process rituals presented as achievements.","example":"Implemented structured workflows, including chat-based standups, to improve coordination.","whyBad":"Describes what every competent holder of the role does by default; the line displaces a real outcome. Prioritization noise.","detection":"Standups, ceremonies, 'introduced code reviews' (existing at all) as standalone bullets at lead+.","dimensionIds":["content_prioritization","seniority_alignment"],"derivedFromUnitIds":["u-twq-standups"]}$ocv1$::jsonb, 'operator_cv', true, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Anti-pattern — AI verb costume', null, null, 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:anti:ap-ai-verb-costume","ingestionVersion":"operator_cv_ingestion_v1","kind":"anti_pattern","antiPatternId":"ap-ai-verb-costume","name":"AI verb costume","description":"Grandiose verbs where plain ones are natural, and uniform sentence machinery.","example":"Spearheaded… Leveraged… Orchestrated… Revolutionized… Pioneered… (every bullet, same shape)","whyBad":"Excessive Spearheaded/Leveraged/Orchestrated/Revolutionized/Pioneered, identical bullet skeletons, unnecessary adjectives, and quantified-looking language are the recognizable texture of AI-generated CV prose. The engine must sound like a person: plain strong verbs, varied structure, facts over costume.","detection":"Grandiose-verb density; >2 bullets in a role opening with the same verb; every bullet ending '…resulting in [X]% [abstraction]'; 'results-driven'/'dynamic professional'/'proven track record' in summaries.","dimensionIds":["language_quality","professional_summary"],"derivedFromUnitIds":["u-sum-2023","u-emk-java-150"]}$ocv1$::jsonb, 'operator_cv', true, 'candidate', 'turki');
insert into knowledge.approved_examples (title, role_family, experience_level, language, content, source, anonymized, status, approved_by) values ('Anti-pattern — Bigger title, same register', null, null, 'en', $ocv1${"naturalKey":"operator_cv_ingestion_v1:anti:ap-title-inflation-static-register","ingestionVersion":"operator_cv_ingestion_v1","kind":"anti_pattern","antiPatternId":"ap-title-inflation-static-register","name":"Bigger title, same register","description":"The title rises between versions; the prose stays at the old level.","example":"[Bigger title] with over [N] years of a broad set of skills… (body unchanged from the junior version)","whyBad":"A manager title on mid-level prose is a seniority-alignment failure the reader feels immediately — the claimed level and the demonstrated level disagree.","detection":"Title/level claims not reflected in any bullet's altitude; summaries interchangeable across levels.","dimensionIds":["seniority_alignment","positioning"],"derivedFromUnitIds":["u-sum-2024em"]}$ocv1$::jsonb, 'operator_cv', true, 'candidate', 'turki');
insert into knowledge.before_after_patterns (category, role_family, before_text, after_text, explanation) values ('operator_cv_ingestion_v1:ba-app-bullet-ownership', 'software_engineering', 'Implemented and designed the mobile app with extensive knowledge of ([technology list]) resulting in a seamless user experience and [N]% positive user feedback.', 'Led the development of [the product] using [core technologies], contributing to [verified user-feedback result] and [verified growth result].', 'Self-praise (''with extensive knowledge of'') became an ownership verb; the parenthesized tech dump moved inside the action; the filler adjective (''seamless'') was replaced by the second verified outcome the earlier version already possessed but didn''t use. Every fact in the after exists in the source; nothing was added. [SAFE_TO_REWRITE; dimensions: experience_quality, achievement_impact, language_quality; seniority: senior; language: en; provenance: u-arj-impl-2023 → u-arj-led-2026]');
insert into knowledge.before_after_patterns (category, role_family, before_text, after_text, explanation) values ('operator_cv_ingestion_v1:ba-summary-identity', 'engineering_leadership', '[Title] with over [N] years of a broad set of skills applicable across different sectors and roles, crafting innovative solutions for top companies… Seeking to leverage my expertise to enhance business operations.', '[Title] with [N]+ years leading [team type] in [domain], delivering [platform type] across [sectors]. Experienced in [2–3 technical areas]. Strong background [collaboration surface] while [leadership signal].', 'The generic breadth claim (''broad set of skills'', ''different sectors'') became one specific identity with named domains and sectors; the buzzword verbs and the ''seeking'' objective disappeared; the unverifiable percentage was dropped rather than replaced. Positioning went from ''anyone'' to ''this person''. [SAFE_TO_REWRITE; dimensions: professional_summary, positioning, evidence_specificity; seniority: manager; language: en; provenance: u-sum-2023 → u-sum-2026]');
insert into knowledge.before_after_patterns (category, role_family, before_text, after_text, explanation) values ('operator_cv_ingestion_v1:ba-integration-mechanism', 'software_engineering', 'Managed core banking system integrations with the retail app to streamline financial operations ([named national payment system]).', 'Optimized core banking integrations by developing [language]-based middleware to interface with [named national payment system] for streamlined financial operations.', '''Managed integrations'' hid the person''s actual contribution; the rewrite names the mechanism they built (middleware, in a named language) while keeping the named external system and the purpose. No metric added — the bullet reaches quality 4 on mechanism specificity alone. [SAFE_TO_REWRITE; dimensions: experience_quality, evidence_specificity; seniority: senior; language: en; provenance: u-arj-sarie-2023 → u-arj-middleware]');
insert into knowledge.before_after_patterns (category, role_family, before_text, after_text, explanation) values ('operator_cv_ingestion_v1:ba-portal-structure-not-metric', 'software_engineering', 'Implemented a cutting-edge revamp of [the product], using ([technology list]) which led to customer satisfaction.', 'Modernized [the platform] by improving user experience and collaborating with backend teams on [system types] supporting [named infrastructure], [outcome — pending verification].', 'STRUCTURALLY better: ''cutting-edge'' dropped, platform context and named infrastructure added, collaboration surface stated. BUT the source versions'' outcome mutated between edits (a countable observable became an abstract feeling with the same percentage), so the outcome slot ships empty pending the operator''s answer to the metric-mutation question. A rewrite may improve structure while the fact underneath still needs confirmation. [NEEDS_USER_CONFIRMATION; dimensions: experience_quality, achievement_impact, evidence_specificity; seniority: lead; language: en; provenance: u-emk-portal-2023 → u-emk-portal-2026]');
insert into knowledge.before_after_patterns (category, role_family, before_text, after_text, explanation) values ('operator_cv_ingestion_v1:ba-manager-altitude', 'engineering_leadership', 'Led cross-functional sprints to deliver [the website], aligning development with strategic goals and improving delivery efficiency through Agile practices.', 'Lead [function] for [portfolio/beneficiary], turning early-stage ideas into production-ready products with a focus on [quality criteria].', 'The same role rewritten one altitude up: process ceremonies (sprints, Agile) became the remit they served (a portfolio transformed from ideas to shipped products). Nothing was invented — the later version simply describes the job at the level the title claims. The canonical seniority-alignment rewrite. [SAFE_TO_REWRITE; dimensions: seniority_alignment, leadership_ownership, experience_quality; seniority: manager; language: en; provenance: u-mon-sprints-2024 → u-mon-innovation-2026]');
insert into knowledge.role_patterns (role_family, experience_level, pattern) values ('engineering_leadership', null, $ocv1${"ingestionVersion":"operator_cv_ingestion_v1","kind":"role","id":"engineering_leadership_v1","roleFamily":"engineering_leadership","industry":"technology","expectedSignals":["a remit-level bullet per leadership role: the transformation owned, not the ceremonies attended","people scope made checkable (team size, mentee count) with the mechanisms used","owned artifacts named: technical direction, standards, delivery plans, stakeholder surface","technical credibility at review/guide altitude, not hands-on task claims"],"commonPitfalls":["title rises between versions while the prose register stays at the old level","process vocabulary (sprints, ceremonies) carrying weight outcomes should carry","department-leadership claims with no scope and vapor outcomes","table-stakes rituals (standups) presented as achievements"],"keywordHints":["technical direction","delivery","mentoring","standards","stakeholders","roadmap"]}$ocv1$::jsonb);
